function Metric({ label, value, sub, tone = "primary", icon: Icon }: { label: string; value: string; sub: string; tone?: "primary" | "accent" | "danger" | "sky"; icon: typeof Gauge }) {
  const tones = { primary: "text-primary bg-primary/10", accent: "text-accent bg-accent/10", danger: "text-destructive bg-destructive/10", sky: "text-chart-3 bg-chart-3/10" };
  return <Card className="glass-card group relative overflow-hidden p-5 transition-transform hover:-translate-y-0.5" testId={`card-metric-${label.toLowerCase().replaceAll(" ", "-")}`}><div className="flex items-start justify-between"><div className="font-mono text-[10px] uppercase tracking-[.17em] text-muted-foreground">{label}</div><div className={`grid h-8 w-8 place-items-center rounded-xl ${tones[tone]}`}><Icon size={15} /></div></div><div className="mt-5 font-display text-[29px] font-semibold tracking-[-.06em] text-foreground">{value}</div><div className="mt-1 text-[11px] text-muted-foreground">{sub}</div><div className={`absolute bottom-0 left-0 h-[2px] w-1/3 ${tone === "danger" ? "bg-destructive" : tone === "accent" ? "bg-accent" : tone === "sky" ? "bg-chart-3" : "bg-primary"}`} /></Card>;
}

function ScoreGauge({ score = 78 }: { score?: number }) {
  const circumference = 2 * Math.PI * 47;
  return <div className="relative grid h-[170px] w-[170px] place-items-center"><svg className="absolute inset-0 h-full w-full" viewBox="0 0 110 110"><circle cx="55" cy="55" r="47" fill="none" stroke="hsl(var(--border))" strokeWidth="7" /><circle className="score-ring" cx="55" cy="55" r="47" fill="none" stroke="hsl(var(--primary))" strokeWidth="7" strokeLinecap="round" strokeDasharray={circumference} strokeDashoffset={circumference - (circumference * score) / 100} pathLength={circumference} /></svg><div className="text-center"><div className="font-display text-5xl font-semibold tracking-[-.09em] text-foreground">{score}</div><div className="font-mono text-[9px] uppercase tracking-[.16em] text-muted-foreground">out of 100</div></div></div>;
}

function Sparkline({ data, color = "hsl(var(--primary))" }: { data: number[]; color?: string }) {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const range = max - min || 1;
  const points = data.map((n, i) => `${(i / (data.length - 1)) * 100},${92 - ((n - min) / range) * 75}`).join(" ");
  return <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-14 w-full overflow-visible"><polyline points={points} fill="none" stroke={color} strokeWidth="2.5" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" /></svg>;
}

function SpendTrend({ onSpike }: { onSpike: (label: string) => void }) {
  const values = demoTrends.map((point) => point.value);
  const max = Math.max(...values);
  return <div className="relative h-[210px] pt-2"><div className="absolute inset-x-0 top-3 bottom-8 flex flex-col justify-between">{[16000, 12000, 8000, 4000].map((n) => <div key={n} className="flex items-center gap-3"><span className="w-10 text-right font-mono text-[9px] text-muted-foreground">{formatINR(n, true)}</span><div className="h-px flex-1 border-t border-dashed border-border" /></div>)}</div><div className="absolute inset-x-14 top-4 bottom-9"><Sparkline data={values} color="hsl(var(--primary))" />{demoTrends.map((point, index) => <button key={point.label} aria-label={`Explain spend spike on ${point.label}`} data-testid={`button-explain-spike-${index}`} onClick={() => onSpike(point.label)} className="absolute -ml-2 -mt-2 h-4 w-4 rounded-full border-2 border-background bg-primary transition-transform hover:scale-150" style={{ left: `${(index / (demoTrends.length - 1)) * 100}%`, top: `${95 - (point.value / max) * 78}%` }} />)}</div><div className="absolute bottom-0 left-14 right-0 flex justify-between">{demoTrends.map((p) => <span key={p.label} className="font-mono text-[9px] text-muted-foreground">{p.label}</span>)}</div></div>;
}

function ImportStrip({ onDemo }: { onDemo: () => void }) {
  const [dragging, setDragging] = useState(false);
  const [file, setFile] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const choose = (event: ChangeEvent<HTMLInputElement>) => {
    const selected = event.target.files?.[0];
    if (selected) setFile(selected.name);
  };
  const drop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragging(false);
    const dropped = event.dataTransfer.files?.[0];
    if (dropped) setFile(dropped.name);
  };
  return <Card className="hero-wash overflow-hidden p-5 md:p-7" testId="card-import-first"><div className="flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between"><div className="max-w-xl"><div className="mb-3 inline-flex items-center gap-2 rounded-full border border-primary/25 bg-primary/10 px-3 py-1 font-mono text-[9px] uppercase tracking-[.17em] text-primary"><Sparkles size={12} /> Start with your statement</div><h2 className="font-display text-2xl font-semibold tracking-[-.055em] md:text-3xl">Import once. See the whole story.</h2><p className="mt-2 text-sm leading-relaxed text-muted-foreground">Your statement stays in this workspace. Pulse turns raw transactions into a calm, clear read on where your money moved.</p></div><div className="grid w-full max-w-[470px] grid-cols-2 gap-2 sm:grid-cols-4">{["PhonePe statement", "Google Pay statement", "Razorpay Merchant CSV", "Try Demo Data"].map((item) => <button key={item} onClick={item === "Try Demo Data" ? onDemo : () => { setFile(`${item}.csv`); }} data-testid={`button-import-${item.toLowerCase().replaceAll(" ", "-")}`} className={`group rounded-xl border p-3 text-left transition-transform hover:-translate-y-0.5 ${item === "Try Demo Data" ? "border-primary/40 bg-primary/10" : "border-border bg-background/45 hover:border-primary/35"}`}><div className="mb-2 grid h-7 w-7 place-items-center rounded-lg bg-secondary text-primary">{item === "Try Demo Data" ? <Play size={13} /> : <FileSpreadsheet size={13} />}</div><span className="block text-[11px] font-semibold leading-tight">{item}</span>{item === "Try Demo Data" ? <span className="mt-1 block text-[9px] text-primary">2 min preview</span> : <span className="mt-1 block text-[9px] text-muted-foreground">No login needed</span>}</button>)}</div></div><div onDragOver={(event) => { event.preventDefault(); setDragging(true); }} onDragLeave={() => setDragging(false)} onDrop={drop} data-testid="dropzone-import-overview" className={`mt-6 flex flex-col items-center justify-center rounded-xl border border-dashed p-5 text-center transition-colors lg:mt-7 ${dragging ? "border-primary bg-primary/10" : "border-border bg-background/25"}`}><input ref={inputRef} type="file" accept=".csv,.xlsx" onChange={choose} className="hidden" data-testid="input-import-file" /><UploadCloud size={18} className="mb-2 text-primary" /><p className="text-xs font-semibold">{file ?? "Drop a CSV or XLSX here"}</p><p className="mt-1 text-[10px] text-muted-foreground">or <button onClick={() => inputRef.current?.click()} data-testid="button-browse-import" className="text-primary hover:underline">browse your files</button> · max 25 MB</p>{file ? <span className="mt-2 inline-flex items-center gap-1.5 rounded-md bg-primary/10 px-2 py-1 font-mono text-[9px] text-primary"><Check size={11} /> Ready to review</span> : null}</div></Card>;
}

